const ids = ["G01","G02","G03","G04","G05","G06"];
const results = await Promise.all(ids.map(id => tools.origin_packet({case_id: id})));
const out = [];
for (const r of results) {
  const c = r.cases[0];
  const ev = c.evidence;
  const src = new Map(ev.material_index.map(m=>[m.id, m.source_id]));
  const parents = new Map();
  for (const id of src.keys()) parents.set(id, []);
  for (const l of ev.links) if (l.relation === "derivation") parents.get(l.child)?.push(l.parent);
  // detect cycles via DFS
  const state = new Map(); // 0 unvisited 1 visiting 2 done
  const cyc = [];
  const memo = new Map();
  function resolve(id, stack=[]) {
    if (memo.has(id)) return memo.get(id);
    if (state.get(id)===1) { cyc.push([...stack,id]); return new Set([src.get(id)]); }
    state.set(id,1);
    const ps = parents.get(id)||[];
    let res;
    if (ps.length===0) res = new Set([src.get(id)]);
    else { res = new Set(); for (const p of ps) for (const s of resolve(p,[...stack,id])) res.add(s); }
    state.set(id,2);
    memo.set(id,res);
    return res;
  }
  for (const id of src.keys()) resolve(id);
  const union = new Set();
  for (const id of src.keys()) for (const s of memo.get(id)) union.add(s);
  const q = c.query_ids.map(id=>({material_id:id, origins:[...memo.get(id)].sort()}));
  console.log("====", c.id, "mats", src.size, "union", union.size, "cycles", cyc.length, "leafCount", [...src.keys()].filter(id=>(parents.get(id)||[]).length===0).length);
  console.log("leaf source ids", JSON.stringify([...src.keys()].filter(id=>(parents.get(id)||[]).length===0).map(id=>src.get(id)).sort()));
  console.log("union", JSON.stringify([...union].sort()));
  console.log("queries", JSON.stringify(q));
  out.push({id:c.id, recorded_origin_count:union.size, independence:"unknown", queries:q});
}
return out;

