const ids = ["G01","G02","G03","G04","G05","G06"];
const results = await Promise.all(ids.map(id => tools.origin_packet({case_id: id})));
for (const r of results) {
  const c = r.cases[0]; const ev=c.evidence;
  const src = new Map(ev.material_index.map(m=>[m.id,m.source_id]));
  const parents = new Map([...src.keys()].map(id=>[id,[]]));
  for (const l of ev.links) if(l.relation==="derivation") parents.get(l.child)?.push(l.parent);
  function leaves(id){ const out=new Set(); const stack=[id]; const seen=new Set(); while(stack.length){const x=stack.pop(); if(seen.has(x))continue; seen.add(x); const ps=parents.get(x)||[]; if(!ps.length)out.add(src.get(x)); else stack.push(...ps);} return out; }
  console.log("====",c.id);
  console.log("roots", JSON.stringify([...src.keys()].filter(id=>!(parents.get(id)||[]).length).map(id=>({id,s:src.get(id)}))));
  console.log("queries", JSON.stringify(c.query_ids.map(q=>({q, leaves:[...leaves(q)].sort()}))));
  const all=new Set(); for(const id of src.keys()) for(const s of leaves(id)) all.add(s);
  console.log("allDistinct", all.size, JSON.stringify([...all].sort()));
}
return "ok";
